export function miriArt(prefix,portrait=false){let art=source.replace(/id="([^"]+)"/g,(_,id)=>`id="${prefix}-${id}"`).replace(/url\(#([^)]+)\)/g,(_,id)=>`url(#${prefix}-${id})`);if(portrait)art=art.replace('viewBox="0 0 400 575"','viewBox="142 326 118 139"');return art;}

